// Group papers by (topic, author), sort chronologically, compare adjacent
// stances, and emit one contradiction record whenever the stance changes.

const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => r && Object.keys(r).length > 0);

// Normalize authors_normalized into an array of author names.
function parseAuthors(val) {
  if (Array.isArray(val)) return val;
  if (typeof val === 'string' && val.trim() !== '') {
    try {
      const parsed = JSON.parse(val);
      if (Array.isArray(parsed)) return parsed;
      return [val];
    } catch (e) {
      return [val];
    }
  }
  return [];
}

// Build groups keyed by topic + author.
const groups = {};
const authorSet = new Set();
let papers_checked = 0;

for (const r of rows) {
  papers_checked++;
  const topic = r.topic != null ? String(r.topic) : '';
  const authors = parseAuthors(r.authors_normalized);

  for (const author of authors) {
    const a = String(author).trim();
    if (a === '') continue;
    authorSet.add(a);
    const key = topic + '||' + a;
    if (!groups[key]) groups[key] = { topic, author: a, papers: [] };
    groups[key].papers.push({
      paper_id: r.paper_id != null ? String(r.paper_id) : null,
      year: typeof r.year === 'number' ? r.year : (r.year != null ? Number(r.year) : null),
      stance: r.stance != null ? String(r.stance) : null,
    });
  }
}

const seen = new Set();
const contradictions = [];

for (const key of Object.keys(groups)) {
  const g = groups[key];

  // Sort chronologically; fall back to paper_id when years tie or are null.
  const papers = g.papers.slice().sort((x, y) => {
    const yx = x.year == null ? Infinity : x.year;
    const yy = y.year == null ? Infinity : y.year;
    if (yx !== yy) return yx - yy;
    return String(x.paper_id).localeCompare(String(y.paper_id));
  });

  for (let i = 1; i < papers.length; i++) {
    const earlier = papers[i - 1];
    const later = papers[i];

    // A contradiction event = the stance changed between adjacent papers.
    if (!earlier.stance || !later.stance) continue;
    if (earlier.stance === later.stance) continue;

    // Dedup identical contradiction records.
    const dedupKey = [
      g.author, g.topic,
      earlier.paper_id, earlier.year, earlier.stance,
      later.paper_id, later.year, later.stance,
    ].join('|');
    if (seen.has(dedupKey)) continue;
    seen.add(dedupKey);

    contradictions.push({
      json: {
        author_or_lab: g.author,
        topic: g.topic,
        earlier_paper_id: earlier.paper_id,
        earlier_year: earlier.year,
        earlier_stance: earlier.stance,
        later_paper_id: later.paper_id,
        later_year: later.year,
        later_stance: later.stance,
      },
    });
  }
}

// Attach run-level counts to every emitted item so the summary node can read them.
const authors_checked = authorSet.size;
const contradictions_detected = contradictions.length;

if (contradictions.length === 0) {
  return [{
    json: {
      __no_contradictions: true,
      contradictions_detected: 0,
      authors_checked,
      papers_checked,
    },
  }];
}

for (const c of contradictions) {
  c.json.__contradictions_detected = contradictions_detected;
  c.json.__authors_checked = authors_checked;
  c.json.__papers_checked = papers_checked;
}

return contradictions;

// Read run-level counts from the detection node's output.
const detected = $('Detect Contradictions').all().map((i) => i.json);
const first = detected[0] || {};

let contradictions_detected = 0;
let authors_checked = 0;
let papers_checked = 0;

if (first.__no_contradictions) {
  contradictions_detected = first.contradictions_detected || 0;
  authors_checked = first.authors_checked || 0;
  papers_checked = first.papers_checked || 0;
} else {
  contradictions_detected = first.__contradictions_detected || detected.length;
  authors_checked = first.__authors_checked || 0;
  papers_checked = first.__papers_checked || 0;
}

return [{ json: { contradictions_detected, authors_checked, papers_checked } }];
